        raise TypeError('Both arguments must be strings')
    a_normalized = ''.join(sorted(a.lower().replace(' ', '')))
    b_normalized = ''.join(sorted(b.lower().replace(' ', '')))
    return a_normalized == b_normalized

def is_anagram(a, b):
