import re

def roman_to_int(s):
    if not s or not re.match(r'^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$', s):
        raise ValueError('Invalid Roman numeral')
    mapping = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    prev_value = 0
    for char in reversed(s):
        value = mapping[char]
        if value < prev_value:
            result -= value
        else:
            result += value
        prev_value = value
    return result

import re

def roman_to_int(s):
    if not isinstance(s, str) or not re.match(r'^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$', s):
        raise ValueError('Invalid Roman numeral input')

    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000,
        'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90,
        'CD': 400, 'CM': 900
    }

    i = 0
    num = 0

    while i < len(s):
        if i + 1 < len(s) and s[i:i+2] in roman_map:
            num += roman_map[s[i:i+2]]
            i += 2
        else:
            num += roman_map[s[i]]
            i += 1

    return num

import re

def parse_kv(text):
    result = {}
    pattern = re.compile(r'^\s*([a-z_]+)\s*=\s*(.*)\s*;?$', re.IGNORECASE)
    pairs = text.split(';')
    for pair in pairs:
        pair = pair.strip()
        if pair:
            match = pattern.match(pair)
            if not match:
                raise ValueError(f'Invalid pair: {pair}')
            key, value = match.groups()
            if key in result:
                raise ValueError(f'Duplicate key: {key}')
            result[key] = value.strip()
    return result

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError('Capacity must be greater than 0')
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key not in self.cache:
            return -1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)


